#!/usr/bin/env lua
-- vendor/unicode/gen.lua
--
-- Generates vendor/unicode/eaw.h from the checked-in UCD files. The
-- output is a sorted array of (lo, hi, width) ranges where width is
-- 0 (zero-width / control / combining), 1 (normal printable), or 2
-- (East Asian Wide or Fullwidth).
--
-- The TUI cap layer binary-searches this table to compute cell width
-- for every codepoint it renders. Identical behavior across all
-- platforms (glibc, musl, cosmo, macOS) is the goal — no host
-- wcwidth(3) dependency.
--
-- Run:   lua vendor/unicode/gen.lua > vendor/unicode/eaw.h
-- Refresh upstream data + regenerate: `make fetch-unicode`
--
-- Compatible with Lua 5.1 / 5.4 / LuaJIT (no 5.4-only syntax).

local function parse_codepoint(s)
    return tonumber(s, 16)
end

-- Read EastAsianWidth.txt — maps codepoints to W / F / H / Na / A / N.
-- Lines look like:
--   0020;Na # Zs SPACE
--   4E00..9FFF;W # Lo [20480] CJK UNIFIED IDEOGRAPH-4E00
local function read_eaw(path)
    local out = {}
    local f, err = io.open(path, "rb")
    if not f then error("cannot open " .. path .. ": " .. tostring(err)) end
    for line in f:lines() do
        if line ~= "" and line:sub(1, 1) ~= "#" then
            local lo_hex, hi_hex, prop = line:match("^(%x+)%.%.(%x+)%s*;%s*(%a+)")
            if not lo_hex then
                lo_hex, prop = line:match("^(%x+)%s*;%s*(%a+)")
                hi_hex = lo_hex
            end
            if lo_hex and prop then
                local lo, hi = parse_codepoint(lo_hex), parse_codepoint(hi_hex)
                for cp = lo, hi do out[cp] = prop end
            end
        end
    end
    f:close()
    return out
end

-- Read UnicodeData.txt — semicolon-separated. Field 0 = codepoint hex,
-- field 1 = name, field 2 = general category. Range markers look like
-- "<CJK Ideograph, First>" / "<CJK Ideograph, Last>".
local function read_gc(path)
    local out = {}
    local f, err = io.open(path, "rb")
    if not f then error("cannot open " .. path .. ": " .. tostring(err)) end
    local range_start, range_cat = nil, nil
    for line in f:lines() do
        local cp_hex, name, cat = line:match("^(%x+);([^;]*);([^;]*)")
        if cp_hex and cat then
            local cp = parse_codepoint(cp_hex)
            if name:find(", First>$") then
                range_start, range_cat = cp, cat
            elseif name:find(", Last>$") and range_start then
                for c = range_start, cp do out[c] = range_cat end
                range_start = nil
            else
                out[cp] = cat
            end
        end
    end
    f:close()
    return out
end

-- Width classification used by Hull's TUI:
--   0  zero-width: combining marks (Mn/Mc/Me), format chars (Cf),
--      control chars (Cc), surrogates (Cs), and U+00AD soft hyphen
--   2  East Asian Wide (W) or Fullwidth (F)
--   1  everything else
--
-- Cc returns 0 because terminals render control bytes as escape
-- sequences or empty; the script should never feed them into the
-- cell buffer. Co (private use) returns 1 — the best guess.
local function width_of(cp, gc, eaw)
    if cp == 0x00AD then return 0 end          -- soft hyphen
    if gc == "Mn" or gc == "Mc" or gc == "Me" then return 0 end
    if gc == "Cf" or gc == "Cc" or gc == "Cs" then return 0 end
    if eaw == "W" or eaw == "F" then return 2 end
    return 1
end

-- ── main ────────────────────────────────────────────────────────────
local script_dir = arg[0]:match("^(.*)/") or "."
local eaw_path = arg[1] or (script_dir .. "/EastAsianWidth.txt")
local ucd_path = arg[2] or (script_dir .. "/UnicodeData.txt")

local eaw = read_eaw(eaw_path)
local gc  = read_gc(ucd_path)

-- Walk every codepoint and compress consecutive same-width runs.
local ranges = {}
local cur_w = width_of(0, gc[0] or "Cn", eaw[0] or "N")
local cur_lo = 0
local cur_hi = 0
for cp = 1, 0x10FFFF do
    local w = width_of(cp, gc[cp] or "Cn", eaw[cp] or "N")
    if w == cur_w then
        cur_hi = cp
    else
        ranges[#ranges + 1] = { lo = cur_lo, hi = cur_hi, w = cur_w }
        cur_lo, cur_hi, cur_w = cp, cp, w
    end
end
ranges[#ranges + 1] = { lo = cur_lo, hi = cur_hi, w = cur_w }

-- Drop trailing default-width-1 ranges from the table: the runtime
-- lookup defaults to 1 when no range matches, so we don't need to
-- store them.
local last = #ranges
while last > 0 and ranges[last].w == 1 do last = last - 1 end

-- Also collapse any internal default-1 ranges next to each other
-- (shouldn't happen after the walk above, but cheap to be safe).
local out = {}
for i = 1, last do
    local r = ranges[i]
    if #out > 0 and out[#out].w == r.w and out[#out].hi + 1 == r.lo then
        out[#out].hi = r.hi
    else
        out[#out + 1] = r
    end
end

-- Emit C header.
local header = [[
/* vendor/unicode/eaw.h — Generated by vendor/unicode/gen.lua.
 * DO NOT EDIT BY HAND. Refresh via `make fetch-unicode`.
 *
 * Source: EastAsianWidth.txt + UnicodeData.txt (Unicode 16.0.0).
 *
 * The table is sorted by `lo`. Lookup uses binary search to find
 * the range containing the target codepoint; codepoints with no
 * match default to width 1 (normal printable).
 *
 * Width values:
 *   0  zero-width (combining marks, format, control, soft hyphen)
 *   2  East Asian Wide or Fullwidth
 *   1  everything else (default; not stored explicitly)
 *
 * SPDX-License-Identifier: AGPL-3.0-or-later
 */

#ifndef HL_UNICODE_EAW_H
#define HL_UNICODE_EAW_H

#include <stddef.h>
#include <stdint.h>

typedef struct {
    uint32_t lo;
    uint32_t hi;
    uint8_t  width;
} HlEawRange;

static const HlEawRange hl_eaw_ranges[] = {
]]
io.write(header)
for i = 1, #out do
    local r = out[i]
    io.write(string.format("    { 0x%05X, 0x%05X, %d },\n", r.lo, r.hi, r.w))
end
io.write(string.format([[
};

static const size_t hl_eaw_ranges_count =
    sizeof(hl_eaw_ranges) / sizeof(hl_eaw_ranges[0]);

#endif /* HL_UNICODE_EAW_H */
]]))
